module adder_16bit(
    input [15:0] a,
    input [15:0] b,
    input Cin,
    output [15:0] y,
    output Co
    );

    wire [15:0] a1;
    wire [15:0] b1;
    wire G;
    wire [15:0] Y;
    wire C;

    assign a1 = a;
    assign b1 = b;
    assign G = Cin;
    assign {C, Y} = a1 + b1 + G;

    assign y = Y;
    assign Co = C;

endmodule
